SELECT SUM(CASE WHEN a.element = 'cl' THEN 1 ELSE 0 END) * 100.0 / COUNT(a.atom_id) AS percent
FROM atom a
WHERE a.molecule_id IN (SELECT molecule_id FROM bond WHERE bond_type = '-');

SELECT CAST(SUM(bond.bond_type = '-') AS REAL) * 100 / COUNT(connected.bond_id) AS percentage
FROM connected
JOIN bond ON connected.bond_id = bond.bond_id;

SELECT s.AdmLName1, s.District, s.County, s.School
FROM schools s
WHERE s.CharterNum = '40';

SELECT p.ViewCount
FROM posts p
WHERE p.Title = 'Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer';

SELECT DisplayName
FROM users
WHERE WebsiteUrl = 'http://stackoverflow.com';

SELECT Text
FROM comments
WHERE UserId IN (SELECT Id FROM users WHERE DisplayName = 'A Lion');

SELECT COUNT(DISTINCT CASE WHEN b.Name = 'Teacher' THEN b.UserId END) * 100.0 / COUNT(DISTINCT b.UserId) AS Percentage
FROM badges b
JOIN users u ON b.UserId = u.Id;

SELECT s.AdmFName1, s.AdmLName1, s.AdmFName2, s.AdmLName2, s.AdmFName3, s.AdmLName3, s.School, s.City
FROM schools s
WHERE s.Charter = 1 AND s.CharterNum = '00D2';

SELECT users.DisplayName
FROM users
WHERE users.Age BETWEEN 19 AND 65;

SELECT 100.0 * COUNT(CASE WHEN u1.Age BETWEEN 13 AND 18 THEN u1.Id END) / COUNT(u1.Id) AS percentage
FROM users u1
JOIN users u2 ON u1.Id = u2.Id;

SELECT
  (SELECT COUNT(*) FROM posts WHERE OwnerUserId IN (SELECT Id FROM users WHERE CreationDate = (SELECT MAX(CreationDate) FROM users))) AS NumberOfPosts,
  (SELECT COUNT(*) FROM comments WHERE UserId IN (SELECT Id FROM users WHERE CreationDate = (SELECT MAX(CreationDate) FROM users))) AS NumberOfComments;

SELECT u.Reputation, u.Views
FROM users u
WHERE u.DisplayName = 'Jarrod Dixon';

SELECT CAST(SUM(CASE WHEN c1.Currency = 'EUR' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN c1.Currency = 'CZK' THEN 1 ELSE 0 END) AS ratio
FROM customers c1
JOIN customers c2 ON c1.CustomerID = c2.CustomerID;

SELECT COUNT(CASE WHEN b.Name = 'Teacher' THEN 1 END) * 100.0 / COUNT(b.UserId) AS percentage
FROM badges b
JOIN users u ON b.UserId = u.Id;

SELECT Name
FROM badges
WHERE UserId IN (
    SELECT Id
    FROM users
    WHERE Reputation = (
        SELECT MIN(Reputation)
        FROM users
    )
);

SELECT p.LastEditDate, p.LastEditorUserId
FROM posts p
WHERE p.Title = 'Detecting a given face in a database of facial images';

SELECT COUNT(CASE WHEN strftime('%Y', posts.CreaionDate) = '2011' AND users.Reputation > 1000 THEN posts.Id END) * 100.0 / COUNT(posts.Id) AS percentage
FROM posts
JOIN users ON posts.OwnerUserId = users.Id;

SELECT CAST(SUM(CASE WHEN P.player_name = 'Abdou Diallo' THEN PA.ball_control ELSE 0 END) AS REAL) / COUNT(CASE WHEN P.player_name = 'Abdou Diallo' THEN PA.id ELSE NULL END) - CAST(SUM(CASE WHEN P.player_name = 'Aaron Appindangoye' THEN PA.ball_control ELSE 0 END) AS REAL) / COUNT(CASE WHEN P.player_name = 'Aaron Appindangoye' THEN PA.id ELSE NULL END) AS difference
FROM Player P
JOIN Player_Attributes PA ON P.player_api_id = PA.player_api_id;

SELECT SUM(CASE WHEN g.Country = 'CZE' THEN 1 ELSE 0 END) - SUM(CASE WHEN g.Country = 'SVK' THEN 1 ELSE 0 END) AS more_discount_stations
FROM gasstations g
WHERE g.Segment = 'Discount';

SELECT 100.0 * SUM(CASE WHEN g.Segment = 'Premium' THEN 1 ELSE 0 END) / COUNT(*) AS premium_percentage
FROM gasstations g
WHERE g.Country = 'SVK';

SELECT DISTINCT p.player_name
FROM Player p
WHERE p.height > 180;

SELECT 100.0 * SUM(CASE WHEN PA.stamina > 80 AND PA.strength > 80 THEN 1 ELSE 0 END) / COUNT(*)
FROM Player_Attributes PA
JOIN Player P ON PA.player_api_id = P.player_api_id;

SELECT 100.0 * SUM(CASE WHEN l.status = 'C' THEN l.amount ELSE 0 END) / SUM(l.amount) AS percentage
FROM loan l
WHERE l.amount < 100000;

SELECT SUM(CASE WHEN d.A3 = 'north Bohemia' THEN d.A16 ELSE 0 END) - SUM(CASE WHEN d.A3 = 'east Bohemia' THEN d.A16 ELSE 0 END) AS crime_difference
FROM district d
WHERE d.A3 IN ('north Bohemia', 'east Bohemia');

SELECT DISTINCT department
FROM major
WHERE college LIKE '%Humanities%Social%';

SELECT SUM(major.major_name = 'Finance') * 1.0 / SUM(major.major_name = 'Physics') AS ratio
FROM member
JOIN major ON member.link_to_major = major.major_id;

SELECT SUM(CASE WHEN member.position = 'Member' AND major.major_name = 'Business' THEN 1 ELSE 0 END) * 100.0 / COUNT(member.member_id) AS percentage
FROM member
JOIN major ON member.link_to_major = major.major_id;

SELECT DISTINCT event.type
FROM event
WHERE event.location = 'MU 215';

SELECT DISTINCT z.state
FROM zip_code z
WHERE z.type = 'PO Box';

SELECT 100.0 * COUNT(DISTINCT CASE WHEN pa.strength > 80 AND pa.stamina > 80 THEN pa.player_api_id END) / COUNT(DISTINCT pa.player_api_id) AS percentage
FROM Player p
JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id;

SELECT COUNT(CASE WHEN p.height < 180 AND pa.overall_rating > 70 THEN 1 END) * 100.0 / COUNT(pa.id) AS percentage
FROM Player p
JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id;

SELECT SUM(CASE WHEN status = 'C' THEN amount ELSE 0 END) * 100.0 / SUM(amount) AS percentage
FROM loan
WHERE amount < 100000;

SELECT
  (SELECT frequency FROM account WHERE account_id = 3) AS statement_release_frequency,
  (SELECT k_symbol FROM trans WHERE account_id = 3 AND type = 'VYDAJ' GROUP BY k_symbol HAVING SUM(amount) = 3539 LIMIT 1) AS debit_purpose;

SELECT SUM(CASE WHEN SUBSTR(e.event_date, 1, 4) = '2019' THEN b.spent ELSE 0 END) - SUM(CASE WHEN SUBSTR(e.event_date, 1, 4) = '2020' THEN b.spent ELSE 0 END) AS spent_difference
FROM budget b
JOIN event e ON b.link_to_event = e.event_id;

SELECT DISTINCT major.department
FROM major
WHERE major.college = 'College of Humanities and Social Sciences';

SELECT SUM(major_name = 'Finance') * 1.0 / SUM(major_name = 'Physics') AS ratio
FROM member
JOIN major ON member.link_to_major = major.major_id;

SELECT SUM(m.position = 'Member' AND mj.major_name = 'Business') * 100.0 / COUNT(m.member_id) AS percentage
FROM member m
JOIN major mj ON m.link_to_major = mj.major_id;

SELECT CAST(SUM(b.remaining < 0) AS REAL) * 100 / COUNT(e.event_id) AS percentage
FROM event e
JOIN budget b ON e.event_id = b.link_to_event;

SELECT superhero_name, CAST(SUM(height_cm) AS REAL) / COUNT(*) AS average_height
FROM superhero
GROUP BY superhero_name;

SELECT SUM(CASE WHEN colour.colour = 'Blue' THEN 1 ELSE 0 END) * 100.0 / COUNT(superhero.superhero_name) AS percentage
FROM superhero
LEFT JOIN colour ON superhero.eye_colour_id = colour.id;

SELECT CAST(SUM(CASE WHEN superhero.gender_id = 1 THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN superhero.gender_id = 2 THEN 1 ELSE 0 END) AS ratio
FROM superhero
JOIN gender ON superhero.gender_id = gender.id;

SELECT s.full_name
FROM superhero s
WHERE s.superhero_name = 'Alien';

SELECT SUM(CASE WHEN p.SEX = 'F' AND (CAST(l.TP AS REAL) < 6.0 OR CAST(l.TP AS REAL) > 8.5) THEN 1 ELSE 0 END) * 100.0 / COUNT(l.ID) AS percentage
FROM Patient p
JOIN Laboratory l ON p.ID = l.ID;

SELECT SUM(Diagnosis = 'BEHCET') * 100.0 / COUNT(*)
FROM Patient
WHERE SEX = 'M' AND strftime('%Y', `First Date`) = '1981';

SELECT EXISTS (
  SELECT 1 FROM molecule
  WHERE molecule_id = (
    SELECT molecule_id FROM bond
    WHERE bond_type = ' = '
    GROUP BY molecule_id
    ORDER BY COUNT(bond_id) DESC
    LIMIT 1
  ) AND label = '+'
);

SELECT SUM(CASE WHEN b.remaining < 0 THEN 1 ELSE 0 END) * 100.0 / COUNT(e.event_id) AS percentage
FROM event AS e
JOIN budget AS b ON e.event_id = b.link_to_event;

SELECT SUM(CASE WHEN colour.colour = 'Blue' THEN 1 ELSE 0 END) * 100.0 / COUNT(superhero.superhero_name) AS percentage
FROM superhero
LEFT JOIN colour ON superhero.eye_colour_id = colour.id;

SELECT CAST(SUM(CASE WHEN g.gender = 'Male' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN g.gender = 'Female' THEN 1 ELSE 0 END) AS ratio
FROM superhero s
JOIN gender g ON s.gender_id = g.id;

SELECT 100.0 * SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) / SUM(CASE WHEN Admission = '-' THEN 1 ELSE 0 END) AS deviation_percentage
FROM Patient
WHERE SEX = 'M';

SELECT MIN(CAST(strftime('%Y', P."First Date") AS INTEGER) - CAST(strftime('%Y', P.Birthday) AS INTEGER)) AS age
FROM Patient P
JOIN Examination E ON P.ID = E.ID;

SELECT CAST(COUNT(DISTINCT CASE WHEN p.SEX = 'M' AND l.UA <= '8.0' THEN p.ID END) AS REAL) / COUNT(DISTINCT CASE WHEN p.SEX = 'F' AND l.UA <= '6.5' THEN p.ID END) AS ratio
FROM Patient p
JOIN Laboratory l ON p.ID = l.ID;

SELECT 100.0 * COUNT(DISTINCT CASE WHEN b.bond_type = '#' THEN m.molecule_id END) / COUNT(DISTINCT m.molecule_id) AS percent_triple_bond
FROM molecule m
LEFT JOIN bond b ON b.molecule_id = m.molecule_id;

SELECT CAST(SUM(CASE WHEN molecule.label = '+' AND atom.element = 'cl' THEN 1 ELSE 0 END) AS REAL) / CAST(COUNT(molecule.molecule_id) AS REAL) AS percentage
FROM molecule
JOIN atom ON molecule.molecule_id = atom.molecule_id;

SELECT 100.0 * COUNT(DISTINCT CASE WHEN b.bond_type = '#' THEN m.molecule_id END) / COUNT(DISTINCT m.molecule_id) AS percent_triple_bond
FROM molecule m
LEFT JOIN bond b ON b.molecule_id = m.molecule_id;

SELECT CAST(SUM(CASE WHEN molecule.label = '+' AND atom.element = 'cl' THEN 1 ELSE 0 END) AS REAL) / CAST(COUNT(molecule.molecule_id) AS REAL) AS percentage
FROM molecule
JOIN atom ON molecule.molecule_id = atom.molecule_id;
